import app from 'flarum/forum/app';
import UserSearchResult from 'flarum/common/components/UserSearchResult';
import Button from 'flarum/common/components/Button';
import SearchManager from 'flarum/common/SearchManager';
export default class UsersSearchSourceWithoutInternalRouting {
  results = (() => new Map())();
  constructor(onselect) {
    this.onselect = onselect;
  }
  async search(query) {
    return app.store.find('users', {
      filter: {
        q: query
      },
      page: {
        limit: 5
      }
    }).then(results => {
      this.results.set(query, results);
      m.redraw();
    });
  }
  view(query) {
    const lowerQuery = query.toLowerCase();
    const results = (this.results.get(lowerQuery) || []).concat(app.store.all('users').filter(user => [user.username(), user.displayName()].some(value => value.toLowerCase().substring(0, lowerQuery.length) === lowerQuery))).filter((e, i, arr) => arr.lastIndexOf(e) === i).sort((a, b) => a.displayName().localeCompare(b.displayName()));
    const minLength = SearchManager.minSearchLength();
    const typeMore = () => m("li", null, m(Button, {
      icon: "fas fa-info-circle"
    }, app.translator.trans('fof-author-change.forum.search.type-more-characters', {
      count: minLength
    })));
    const tooShort = SearchManager.queryLength(lowerQuery) < minLength;
    if (results.length === 0) {
      if (tooShort) {
        return [typeMore()];
      }
      return [m("li", null, m(Button, {
        icon: "fas fa-search-minus"
      }, app.translator.trans('fof-author-change.forum.search.no-results')))];
    }
    const items = results.map(user => m(UserSearchResult, {
      user: user,
      query: query,
      onclick: () => this.onselect(user)
    }));
    if (tooShort) {
      items.push(typeMore());
    }
    return items;
  }
}
flarum.reg.add('fof-author-change', 'forum/components/UsersSearchSourceWithoutInternalRouting', UsersSearchSourceWithoutInternalRouting);